import{_ as t,o as h,c as i,b6 as a,mg as c,mh as g,mi as r,mj as o,mk as m,ml as p,mm as u,mn as l,mo as e,mp as s,mq as d,mr as b,ms as v,mt as y,mu as k,mv as q,mw as T,mx as _,my as C,mz as x,mA as P,mB as I,mC as W,mD as D,mE as f,mF as A,mG as w,mH as B,mI as N,mJ as M,mK as S,mL as R,mM as H,mN as X,mO as V,mP as K,mQ as G,mR as Q,mS as L,mT as O,mU as U,mV as E}from"./chunks/framework.BUXTSoD9.js";const tn=JSON.parse('{"title":"Cách Xây dựng Ứng dụng WeChat Mini Program Đơn giản nhất","description":"","frontmatter":{},"headers":[],"relativePath":"vi-vn/stage-3/cross-platform/wechat-miniprogram/index.md","filePath":"vi-vn/stage-3/cross-platform/wechat-miniprogram/index.md"}'),z={name:"vi-vn/stage-3/cross-platform/wechat-miniprogram/index.md"};function F(Y,n,$,j,J,Z){return h(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="cach-xay-dung-ung-dung-wechat-mini-program-đon-gian-nhat" tabindex="-1">Cách Xây dựng Ứng dụng WeChat Mini Program Đơn giản nhất <a class="header-anchor" href="#cach-xay-dung-ung-dung-wechat-mini-program-đon-gian-nhat" aria-label="Permalink to “Cách Xây dựng Ứng dụng WeChat Mini Program Đơn giản nhất”">​</a></h1><h1 id="_1-ung-dung-wechat-mini-program-va-phat-trien-mini-program-la-gi" tabindex="-1">1. Ứng dụng WeChat Mini Program và Phát triển Mini Program là gì <a class="header-anchor" href="#_1-ung-dung-wechat-mini-program-va-phat-trien-mini-program-la-gi" aria-label="Permalink to “1. Ứng dụng WeChat Mini Program và Phát triển Mini Program là gì”">​</a></h1><p>Trong hướng dẫn này, chúng ta sẽ hoàn thành một vòng lặp khép kín: từ một ý tưởng trong đầu bạn đến một mini program thực sự có thể được tìm kiếm và mở bằng mã QR trong WeChat.</p><p>Trước khi bắt đầu xây dựng, chúng ta cần thiết lập hai hiểu biết cơ bản.</p><p>Thứ nhất là <strong>bản chất</strong>: chính xác thì mini program WeChat là gì? Nó khác gì với ứng dụng hoặc trang web thông thường? Tại sao nhiều sản phẩm chọn định dạng này? Chỉ khi bạn hiểu logic cốt lõi thì mới có thể đánh giá ý tưởng của bạn có phù hợp với mini program hay không.</p><p>Thứ hai là <strong>con đường</strong>: khi bạn nói &quot;tôi muốn xây một mini program,&quot; con đường đầy đủ từ không đến khi ra mắt trông như thế nào? Các nút then chốt trên con đường đó là gì - cần suy nghĩ gì trong giai đoạn ý tưởng, cách thiết lập môi trường, cách phát triển có hỗ trợ AI cải thiện hiệu quả, những cạm bẫy nào xuất hiện khi gỡ lỗi trên trình mô phỏng và tài khoản thử nghiệm so với phát hành chính thức giải quyết điều gì. Nếu bạn chạy qua quy trình này trong đầu trước, bạn sẽ không bị lạc trong quá trình triển khai.</p><p>Sau khi hai câu hỏi này rõ ràng, chúng ta có thể chính thức bước vào phát triển. Hãy bắt đầu với câu hỏi đầu tiên: chính xác thì mini program WeChat là gì?</p><h2 id="_1-1-ung-dung-wechat-mini-program" tabindex="-1">1.1 Ứng dụng WeChat Mini Program <a class="header-anchor" href="#_1-1-ung-dung-wechat-mini-program" aria-label="Permalink to “1.1 Ứng dụng WeChat Mini Program”">​</a></h2><p>Một mini program WeChat có thể được xem như một ứng dụng sống bên trong WeChat. Bạn không cần tìm kiếm trong cửa hàng ứng dụng, tải xuống hay cài đặt. Người dùng có thể tìm theo tên trong WeChat, quét mã QR hoặc mở một thẻ chia sẻ và sử dụng ngay lập tức. Sau khi sử dụng, chỉ cần đóng lại. Nó không chiếm dụng màn hình chính hoặc bộ nhớ điện thoại vĩnh viễn.</p><p>Đối với người dùng thông thường, mini program giải quyết nhiều &quot;nhiệm vụ nhỏ&quot;: theo dõi giao hàng, đặt cà phê, xem đơn hàng, chơi một trò chơi nhanh. Khởi động nhanh và điểm truy cập thống nhất trong WeChat là đặc điểm trải nghiệm lớn nhất.</p><p>Đối với công ty và nhà phát triển, mini program là một &quot;định dạng ứng dụng nhỏ&quot; có thể tìm kiếm và chia sẻ được. Miễn là bạn đăng ký trên Nền tảng Chính thức WeChat, hoàn tất cài đặt và vượt qua kiểm duyệt, mini program của bạn có thể mở cho tất cả người dùng WeChat. So với ứng dụng truyền thống, dễ dàng hơn để có được nhóm người dùng đầu tiên vì mọi người đã quen làm nhiều việc trong WeChat.</p><p>Trong hướng dẫn này, chúng ta sẽ không xây dựng một hệ thống kinh doanh phức tạp. Chúng ta chọn một ví dụ kinh điển: trò chơi Rắn. Nó nhỏ gọn và logic rõ ràng, nhưng bao gồm đầy đủ các yếu tố mà một mini program nên có: nhiều trang, tương tác đơn giản, thay đổi trạng thái, ghi điểm, v.v. Hoàn hảo làm dự án đầu tiên của bạn.</p><h2 id="_1-2-phat-trien-ung-dung-wechat-mini-program" tabindex="-1">1.2 Phát triển Ứng dụng WeChat Mini Program <a class="header-anchor" href="#_1-2-phat-trien-ung-dung-wechat-mini-program" aria-label="Permalink to “1.2 Phát triển Ứng dụng WeChat Mini Program”">​</a></h2><p>Sau khi hiểu &quot;mini program là gì,&quot; câu hỏi tiếp theo là: phát triển một mini program thực sự bao gồm những gì?</p><p>Bạn cần một mục tiêu rõ ràng (ví dụ, một trò chơi Rắn mà người dùng có thể chơi bất cứ lúc nào), thiết kế giao diện mà người dùng sẽ thấy, xác định điều gì sẽ xảy ra dưới các hành động khác nhau và cuối cùng là xuất bản nó.</p><p>Trong phát triển truyền thống, lập trình viên thường dẫn dắt tất cả các bước này và viết rất nhiều mã. Trong phát triển có hỗ trợ AI, điều này có thể được chia rõ ràng hơn: bạn giải thích những gì bạn muốn và AI giúp với hầu hết các chi tiết triển khai. Điều đó có nghĩa là đối với người mới bắt đầu, kỹ năng quan trọng nhất không còn là ghi nhớ cú pháp mà là mô tả rõ ràng yêu cầu và hiểu đầu ra của AI.</p><h2 id="_1-3-mot-so-cach-phat-trien-ung-dung-wechat-mini-program" tabindex="-1">1.3 Một số Cách Phát triển Ứng dụng WeChat Mini Program <a class="header-anchor" href="#_1-3-mot-so-cach-phat-trien-ung-dung-wechat-mini-program" aria-label="Permalink to “1.3 Một số Cách Phát triển Ứng dụng WeChat Mini Program”">​</a></h2><p>Trong dự án thực tế, mọi người sử dụng các lộ trình kỹ thuật khác nhau. Để tránh làm bạn quá tải với thuật ngữ ngay từ đầu, chúng ta sẽ chỉ phân loại sơ bộ để bạn hiểu các con đường phổ biến.</p><p>Cách đầu tiên là sử dụng trực tiếp các khả năng gốc chính thức. Sau khi tạo dự án trong WeChat DevTools, bạn sẽ thấy một bộ tệp cố định được sử dụng để mô tả cấu trúc trang, kiểu dáng và logic. Cách này bám sát tài liệu chính thức và có khả năng kiểm soát mạnh, nhưng đối với người mới học frontend lần đầu, đường cong học tập hơi dốc hơn.</p><p>Cách thứ hai là sử dụng framework đa nền tảng, như uni-app. Bạn chủ yếu viết mã giống web cục bộ (ví dụ tệp <code>.vue</code>) và framework chuyển đổi mã này sang định dạng mà mini program WeChat có thể chạy. Ưu điểm là cấu trúc thống nhất. Nếu bạn sau này xuất bản lên các nền tảng khác (như H5 hoặc App), thay đổi sẽ ít hơn tương đối.</p><p>Dựa trên hai phương pháp này, hướng dẫn này tập trung vào SOP mini program sử dụng công cụ có hỗ trợ AI. Ví dụ, mở toàn bộ dự án trong Trae và nói trực tiếp với AI tích hợp: &quot;Vui lòng thêm trang chủ với tiêu đề và nút trong tệp này&quot; hoặc &quot;Vui lòng tạo trang trò chơi hiển thị con rắn và điểm số.&quot; AI sẽ tạo đoạn mã mới hoặc sửa đổi/tái cấu trúc mã hiện có dựa trên ngữ cảnh dự án hiện tại.</p><p>Ba cách này không loại trừ lẫn nhau. Bạn hoàn toàn có thể xây dựng trong dự án uni-app đồng thời sử dụng Trae AI cho hầu hết công việc lập trình. Điều quan trọng không phải là chọn một phương pháp mà là biết bạn đang ở đâu và những công cụ nào có sẵn.</p><h2 id="_1-4-cac-buoc-phat-trien-ung-dung-wechat-mini-program-đuoc-trinh-bay-trong-bai-viet-nay-xem-truoc-tong-quan" tabindex="-1">1.4 Các Bước Phát triển Ứng dụng WeChat Mini Program được Trình bày trong Bài viết này (Xem trước Tổng quan) <a class="header-anchor" href="#_1-4-cac-buoc-phat-trien-ung-dung-wechat-mini-program-đuoc-trinh-bay-trong-bai-viet-nay-xem-truoc-tong-quan" aria-label="Permalink to “1.4 Các Bước Phát triển Ứng dụng WeChat Mini Program được Trình bày trong Bài viết này (Xem trước Tổng quan)”">​</a></h2><p>Hướng dẫn này tuân theo nhịp độ từ <strong>môi trường đến sản phẩm cuối cùng</strong>. Xung quanh ví dụ Rắn và phong cách vibecoding Trae, chúng ta chia quy trình thành một lộ trình có thể tái sử dụng. Trong các chương sau, bạn sẽ đi qua các giai đoạn này:</p><ol><li>Xây dựng nền tảng khái niệm: hiểu mini program là gì, các phương pháp phát triển phổ biến và đối tượng mà trò chơi Rắn mini program này phục vụ và trong những tình huống nào.</li><li>Chuẩn bị môi trường: đăng ký tài khoản mini program, cài đặt HBuilderX, Trae và WeChat DevTools, sau đó tạo khung dự án cơ bản với HBuilderX có thể chạy trong WeChat DevTools và hiển thị trang đơn giản nhất trước tiên.</li><li>Bước vào phát triển chính thức: mở dự án trong Trae, sử dụng hộp thoại vibecoding với AI để tạo trang chủ và bố cục trang trò chơi từng bước, triển khai lối chơi cốt lõi như di chuyển rắn, ăn thức ăn và kết thúc trò chơi.</li><li>Sau khi các tính năng cốt lõi chạy, học cách sử dụng AI như một &quot;đối tác gỡ lỗi và tái cấu trúc&quot;: yêu cầu chẩn đoán lỗi, dọn dẹp cấu trúc khi mã trở nên lộn xộn và dần thêm chi tiết như bắt đầu/tạm dừng, ghi điểm cao và làm đẹp UI.</li><li>Bước vào xuất bản: xây dựng dự án thành phiên bản nhận diện được bởi WeChat, xem trước và thử nghiệm trên thiết bị thật trong WeChat DevTools, ra mắt trước bằng tài khoản thử nghiệm và phiên bản trải nghiệm để xác nhận quy trình, sau đó hoàn tất nộp hồ sơ và kiểm duyệt trước khi phát hành chính thức để người khác có thể tìm kiếm và chơi mini program của bạn.</li></ol><p>Phần này chỉ vẽ bản đồ đầy đủ và chưa mở rộng lệnh hoặc chi tiết mã. Hiện tại, hãy nhớ 5 bước này: <strong>Hiểu -&gt; Cài đặt môi trường -&gt; Phát triển Vibecoding -&gt; Gỡ lỗi và tinh chỉnh -&gt; Xây dựng và phát hành</strong>. Các chương sau sẽ phóng to vào từng bước, cho thấy cần chuẩn bị gì, nói gì với AI và kết quả nào bạn sẽ thấy trên màn hình ở mỗi giai đoạn.</p><h1 id="_2-chuan-bi-moi-truong" tabindex="-1">2. Chuẩn bị Môi trường <a class="header-anchor" href="#_2-chuan-bi-moi-truong" aria-label="Permalink to “2. Chuẩn bị Môi trường”">​</a></h1><p>Trước khi viết bất kỳ dòng mã nào, hãy chuẩn bị môi trường trước. Mục tiêu của phần này là đảm bảo bạn không còn bị kẹt ở <strong>chỗ tải công cụ và tại sao mọi thứ không chạy được</strong>, để bạn có thể tập trung trực tiếp vào đối thoại AI và triển khai yêu cầu.</p><p>Nếu bạn có thể mở trình duyệt, tải tệp và nhấp đúp để cài đặt, bạn có thể hoàn thành phần này.</p><h2 id="_2-1-ba-cong-cu-su-dung-trong-huong-dan-nay" tabindex="-1">2.1 Ba Công cụ Sử dụng trong Hướng dẫn này <a class="header-anchor" href="#_2-1-ba-cong-cu-su-dung-trong-huong-dan-nay" aria-label="Permalink to “2.1 Ba Công cụ Sử dụng trong Hướng dẫn này”">​</a></h2><p>Để phát triển mini program Rắn, chúng ta sử dụng ba công cụ cùng nhau, mỗi công cụ có trách nhiệm khác nhau:</p><ol><li>Thứ nhất là Trae. Hãy coi nó như một trình soạn mã tích hợp AI. Nó có thể mở tệp dự án như IDE bình thường và cũng cho phép bạn trò chuyện với AI bằng ngôn ngữ tự nhiên để tạo, sửa đổi và giải thích mã. Hầu hết các hoạt động &quot;xây dựng mini program với AI&quot; trong hướng dẫn này diễn ra trong Trae. Tải phiên bản mới nhất từ <a href="https://www.trae.cn" target="_blank" rel="noreferrer">https://www.trae.cn</a> .</li><li>Thứ hai là HBuilderX. Nó có hỗ trợ mạnh mẽ cho Vue và uni-app, và cung cấp mẫu mini program sẵn có. Chúng ta sử dụng nó để &quot;tạo một cú nhấp chuột&quot; một dự án mini program cơ sở - đây là đặt nền móng trước khi giao cho Trae + AI để tiếp tục lặp lại. Tải từ <a href="https://www.dcloud.io/hbuilderx.html" target="_blank" rel="noreferrer">https://www.dcloud.io/hbuilderx.html</a> .</li><li>Thứ ba là WeChat DevTools. Công cụ chính thức này được sử dụng để phát triển và xem trước mini program. Nó chạy dự án của bạn trên máy tính để bàn và hỗ trợ gỡ lỗi trên thiết bị thật trên điện thoại. Tải từ <a href="https://developers.weixin.qq.com/miniprogram/dev/devtools/download.html" target="_blank" rel="noreferrer">https://developers.weixin.qq.com/miniprogram/dev/devtools/download.html</a> .</li></ol><p>Tóm lại: HBuilderX tạo dự án cơ sở nhanh chóng, Trae giúp bạn lập trình với AI và WeChat DevTools hiển thị mini program đang chạy thực tế.</p><h2 id="_2-2-đang-ky-tai-khoan-nen-tang-chinh-thuc-wechat-va-lay-appid" tabindex="-1">2.2 Đăng ký Tài khoản Nền tảng Chính thức WeChat và Lấy AppID <a class="header-anchor" href="#_2-2-đang-ky-tai-khoan-nen-tang-chinh-thuc-wechat-va-lay-appid" aria-label="Permalink to “2.2 Đăng ký Tài khoản Nền tảng Chính thức WeChat và Lấy AppID”">​</a></h2><p>Với công cụ đã sẵn sàng, bạn vẫn cần một <strong>định danh mini program</strong>, được tạo trên Nền tảng Chính thức WeChat. Nếu bạn chưa từng đăng ký mini program trước đây, hãy làm theo thứ tự này:</p><ol><li>Nhập <a href="https://mp.weixin.qq.com" target="_blank" rel="noreferrer">https://mp.weixin.qq.com</a> trong trình duyệt, mở Nền tảng Chính thức WeChat và đăng nhập bằng cách quét mã QR với WeChat.</li></ol><p><img src="'+c+'" alt=""></p><ol start="2"><li>Chọn &quot;Mini Program&quot; trên trang chủ và hoàn tất lời nhắc đăng ký, bao gồm email, số điện thoại và loại thực thể (cá nhân hoặc doanh nghiệp). <img src="'+g+'" alt=""></li><li>Sau khi đăng ký thành công, vào backend, tìm &quot;Development Management&quot; hoặc &quot;Development Settings&quot; và bạn sẽ thấy một ID duy nhất tên là AppID. Đây là định danh mini program của bạn và sẽ được sử dụng trong cấu hình dự án sau này.</li></ol><p><img src="'+r+'" alt=""></p><p>Khuyến nghị lưu AppID ở nơi dễ tìm. Trong các phần sau, chúng ta sẽ điền trực tiếp giá trị này để ánh xạ dự án cục bộ đến mini program trực tuyến của bạn.</p><h2 id="_2-3-cai-đat-wechat-devtools" tabindex="-1">2.3 Cài đặt WeChat DevTools <a class="header-anchor" href="#_2-3-cai-đat-wechat-devtools" aria-label="Permalink to “2.3 Cài đặt WeChat DevTools”">​</a></h2><p>Tiếp theo chúng ta cần một nơi để thực sự chạy và xem trước mini program. Đó chính xác là những gì WeChat DevTools dùng để làm.</p><ol><li>Truy cập trang tải xuống <a href="https://developers.weixin.qq.com/miniprogram/dev/devtools/download.html" target="_blank" rel="noreferrer">https://developers.weixin.qq.com/miniprogram/dev/devtools/download.html</a> . Trên trang này bạn sẽ thấy các phiên bản cho các hệ điều hành khác nhau. Thường chọn phiên bản ổn định phù hợp với hệ thống của bạn, như Windows 64-bit hoặc macOS.</li><li>Sau khi tải về, nhấp đúp vào trình cài đặt và làm theo hướng dẫn từng bước. Nếu không chắc, giữ các tùy chọn mặc định.</li><li>Sau khi cài đặt, khởi chạy WeChat DevTools từ máy tính để bàn hoặc menu bắt đầu. Khi khởi chạy lần đầu, nó hiển thị mã QR và yêu cầu bạn quét bằng WeChat. Quét và ủy quyền để vào giao diện chính.</li></ol><p><img src="'+o+'" alt=""><img src="'+m+'" alt=""></p><p>Sau này, khi tệp dự án đã sẵn sàng trong Trae, chúng ta sẽ import mini program đã xây dựng vào WeChat DevTools và xem kết quả chạy thực tế tại đây.</p><h2 id="_2-4-chuan-bi-trae-va-hbuilderx" tabindex="-1">2.4 Chuẩn bị Trae và HBuilderX <a class="header-anchor" href="#_2-4-chuan-bi-trae-va-hbuilderx" aria-label="Permalink to “2.4 Chuẩn bị Trae và HBuilderX”">​</a></h2><p>Cuối cùng, cài đặt hai công cụ được sử dụng cho việc lập trình thực tế: Trae và HBuilderX.</p><p>Bạn có thể <strong>cài đặt Trae trước</strong>. Truy cập <a href="https://www.trae.cn" target="_blank" rel="noreferrer">https://www.trae.cn</a> trong trình duyệt và tải phiên bản phù hợp cho hệ điều hành của bạn. Cài đặt như phần mềm bình thường: nhấp đúp vào trình cài đặt và làm theo hướng dẫn. Sau khi cài đặt, bạn có một IDE có thể mở thư mục cục bộ, kiểm tra mã và trò chuyện với AI. Tất cả các bước vibecoding sau đều diễn ra tại đây.</p><p><img src="'+p+'" alt=""></p><p><strong>Sau đó cài đặt HBuilderX</strong>. Truy cập <a href="https://www.dcloud.io/hbuilderx.html" target="_blank" rel="noreferrer">https://www.dcloud.io/hbuilderx.html</a> và tải gói cho hệ điều hành của bạn. HBuilderX nhẹ và khởi động nhanh. Sau khi cài đặt, bạn có thể xem qua giao diện; không cần nghiên cứu sâu tính năng ngay bây giờ. Trong các chương sau, chúng ta sử dụng nó để tạo mẫu uni-app mini program làm điểm bắt đầu dự án.</p><p><img src="'+u+'" alt=""></p><p>Sau khi hoàn thành phần này, môi trường của bạn đã hoàn chỉnh: bạn có tài khoản mini program + AppID, công cụ xem trước thời gian chạy và IDE lập trình AI. Tiếp theo chúng ta bắt đầu từ <strong>tạo khung dự án đầu tiên</strong> và làm cho các công cụ này thực sự chạy.</p><h2 id="_2-5-chuan-bi-tep-co-so" tabindex="-1">2.5 Chuẩn bị Tệp Cơ sở <a class="header-anchor" href="#_2-5-chuan-bi-tep-co-so" aria-label="Permalink to “2.5 Chuẩn bị Tệp Cơ sở”">​</a></h2><ol><li>Nhấp &quot;New Project&quot;.</li></ol><p><img src="'+l+'" alt=""></p><ol start="2"><li>Chọn mẫu mặc định, đặt tên mini program, chọn đường dẫn lưu trữ, sau đó nhấp tạo ở góc dưới bên phải:</li></ol><p><img src="'+e+'" alt=""></p><ol start="3"><li>Màn hình tạo thành công xuất hiện:</li></ol><p><img src="'+s+'" alt=""></p><ol start="4"><li>Sau đó tìm thư mục này trong hệ thống tệp, mở nó trong Trae và bạn sẽ thấy các tệp nền tảng đã sẵn sàng:</li></ol><p><img src="'+d+'" alt=""></p><h1 id="_3-phat-trien-mini-program" tabindex="-1">3. Phát triển Mini Program <a class="header-anchor" href="#_3-phat-trien-mini-program" aria-label="Permalink to “3. Phát triển Mini Program”">​</a></h1><p>Trong hai phần đầu, chúng ta đã làm rõ &quot;mini program là gì&quot; và &quot;cách thiết lập công cụ và môi trường.&quot; Từ phần này, chúng ta bước vào thực hành: không chỉ là khái niệm mà AI thực sự giúp bạn xây dựng mini program Rắn từ không.</p><p>Trong phần này, bạn sẽ đi qua một SOP hoàn chỉnh cho giai đoạn phát triển, bao gồm khoảng:</p><ol><li>Mở dự án hiện tại trong Trae và đưa cho AI chỉ dẫn hoàn chỉnh đầu tiên để nó thiết kế và triển khai phiên bản Rắn có thể chạy dựa trên khung hiện tại.</li><li>Để Trae sửa đổi trực tiếp tệp dự án thực tế, không chỉ xuất &quot;mã mẫu,&quot; và học cách sử dụng rollback để khôi phục trạng thái trước đó khi cần.</li><li>Quay lại HBuilderX và WeChat DevTools, chạy trên trình mô phỏng mini program và chơi phiên bản này trong trình mô phỏng để chuyển từ &quot;góc độ mã&quot; sang &quot;góc độ người dùng.&quot;</li><li>Dựa trên kết quả chơi, tiếp tục đề xuất sửa đổi bằng ngôn ngữ tự nhiên và để AI lặp lại điều khiển từ kiểu nút bấm sang kiểu cần điều khiển, đồng thời trải nghiệm một vòng lặp đầy đủ &quot;tìm vấn đề -&gt; mô tả vấn đề -&gt; AI sửa -&gt; xác minh lại.&quot;</li></ol><p>Bạn có thể chọn thiết kế từng trang và nút trước khi phát triển. Nhưng đối với người mới bắt đầu hoàn toàn, thiết kế giao diện và tương tác bản thân cũng là một lĩnh vực mới (sau này chúng ta sẽ trình bày thiết kế có hỗ trợ AI). Vì vậy trong vòng này, chúng ta cố ý sử dụng cách khác: bắt đầu trước - để AI tạo một phiên bản có thể chạy, sau đó tinh chỉnh dần bằng cách xem hiệu ứng và trò chuyện bằng ngôn ngữ tự nhiên.</p><h2 id="_3-1-giai-thich-yeu-cau-ro-rang-trong-mot-lan-đua-cho-trae-prompt-tong-đau-tien" tabindex="-1">3.1 Giải thích Yêu cầu Rõ ràng trong Một Lần: Đưa cho Trae &quot;Prompt Tổng&quot; Đầu tiên <a class="header-anchor" href="#_3-1-giai-thich-yeu-cau-ro-rang-trong-mot-lan-đua-cho-trae-prompt-tong-đau-tien" aria-label="Permalink to “3.1 Giải thích Yêu cầu Rõ ràng trong Một Lần: Đưa cho Trae &quot;Prompt Tổng&quot; Đầu tiên”">​</a></h2><p>Sau khi mở dự án mini program đã chuẩn bị trong Trae, tôi không vội chỉnh sửa một dòng cụ thể. Thay vào đó, tôi nói với trợ lý AI tích hợp:</p><p><strong>Tôi đã đưa cho AI một lệnh: dựa trên khung hiện tại, xây dựng một mini program Rắn. Vui lòng thiết kế mini program này và viết cho tôi một prompt.</strong></p><p>Nói cách khác, tôi không yêu cầu nó &quot;viết từng hàm một từng bước.&quot; Tôi đưa ra một mục tiêu hoàn chỉnh trước, để AI giúp lập kế hoạch và AI không chỉ lập kế hoạch mà còn trực tiếp hạ cánh triển khai đầu tiên.</p><p>Sau khi nhận được chỉ dẫn này, Trae đọc cấu trúc dự án hiện tại, xác định nơi thêm trang và nơi thêm logic, và trực tiếp sửa đổi tệp/mã dự án. Bạn không cần viết tay mã hoặc tạo/sửa thư mục thủ công.</p><h2 id="_3-2-đe-ai-tu-đong-sua-đoi-ma-thuc-te-khong-lap-trinh-thu-cong" tabindex="-1">3.2 Để AI Tự động Sửa đổi Mã Thực tế, Không Lập trình Thủ công <a class="header-anchor" href="#_3-2-đe-ai-tu-đong-sua-đoi-ma-thuc-te-khong-lap-trinh-thu-cong" aria-label="Permalink to “3.2 Để AI Tự động Sửa đổi Mã Thực tế, Không Lập trình Thủ công”">​</a></h2><p>Khi bạn thực thi chỉ dẫn này trong Trae, AI bước vào quy trình &quot;chỉnh sửa dự án.&quot; Trong quá trình này, bạn có thể quan sát các điểm chính:</p><ol><li>Nó giải thích suy nghĩ của mình trong khu vực trò chuyện, ví dụ thư mục nào sẽ thêm trang và cách tổ chức logic trò chơi.</li></ol><p><img src="'+b+'" alt=""><img src="'+v+'" alt=""></p><ol start="2"><li>Nó trực tiếp chỉnh sửa tệp dự án thực tế, thay vì chỉ đưa &quot;mã mẫu&quot; để sao chép-dán.</li><li>Sau khi hoàn thành, Trae xuất bản tóm tắt ngắn cho bạn biết tệp nào đã thay đổi và đã làm gì.</li></ol><p>Nếu bạn không hài lòng với vòng này (hoặc nghĩ có gì sai), không cần hoảng hả. Trae cung cấp rollback ở góc trên bên ngoài hộp trò chuyện. Bạn có thể khôi phục trạng thái dự án trước khi có chỉ dẫn này bằng một cú nhấp - giống như một phím hoàn tác an toàn.</p><p><img src="'+y+'" alt=""></p><p><img src="'+k+'" alt=""></p><h2 id="_3-3-xem-hieu-ung-trong-hbuilderx-va-wechat-devtools" tabindex="-1">3.3 Xem Hiệu ứng trong HBuilderX và WeChat DevTools <a class="header-anchor" href="#_3-3-xem-hieu-ung-trong-hbuilderx-va-wechat-devtools" aria-label="Permalink to “3.3 Xem Hiệu ứng trong HBuilderX và WeChat DevTools”">​</a></h2><p>Sau khi AI hoàn thành vòng phát triển đầu tiên, mã đã được viết vào dự án, nhưng bạn vẫn chưa thấy hiệu ứng thực tế từ phía người chơi. Tiếp theo chúng ta cần chạy nó.</p><p>Thao tác cụ thể: quay lại HBuilderX, tìm menu trên cùng &quot;Run,&quot; chọn &quot;Run to Mini Program Simulator&quot; -&gt; &quot;WeChat DevTools.&quot; Điều này kích hoạt xây dựng dự án và mở kết quả trong WeChat DevTools.</p><p><img src="'+q+'" alt=""></p><p>Bảng đầu ra ở phía dưới hiển thị quá trình xây dựng. Nếu trạng thái cuối cùng là &quot;ready&quot; không có lỗi, xây dựng thành công. Sau đó chuyển sang WeChat DevTools để kiểm tra UI và tính năng của phiên bản này.</p><p><img src="'+T+'" alt=""></p><p>Trong hầu hết trường hợp, HBuilderX tự động mở WeChat DevTools và bạn có thể trực tiếp thấy mini program đã cập nhật. Nếu không tự động mở, làm như sau:</p><ol><li>Dừng chạy hiện tại trong HBuilderX trước.</li><li>Khởi chạy WeChat DevTools thủ công và giữ nó mở.</li><li>Quay lại HBuilderX, nhấp &quot;Run -&gt; Run to Mini Program Simulator -&gt; WeChat DevTools&quot; lại.</li></ol><p>Sau đó bạn có thể thấy mini program vibecoding trong WeChat DevTools:</p><p><img src="'+_+'" alt=""></p><h2 id="_3-4-su-dung-ngon-ngu-tu-nhien-đe-đieu-chinh-lap-lai-cho-đen-khi-hai-long" tabindex="-1">3.4 Sử dụng Ngôn ngữ Tự nhiên để Điều chỉnh Lặp lại cho đến khi Hài lòng <a class="header-anchor" href="#_3-4-su-dung-ngon-ngu-tu-nhien-đe-đieu-chinh-lap-lai-cho-đen-khi-hai-long" aria-label="Permalink to “3.4 Sử dụng Ngôn ngữ Tự nhiên để Điều chỉnh Lặp lại cho đến khi Hài lòng”">​</a></h2><p>Trong thực hành này, AI ban đầu tạo ra một Rắn điều khiển bằng nút: bốn nút hướng trên màn hình và con rắn đổi hướng khi nhấp. Nó hoàn toàn có thể chơi được, nhưng cá nhân tôi thích điều khiển bằng cần analog. Đối với yêu cầu điều chỉnh của bạn (không chỉ tính năng mà còn thiết kế UI và bố cục; khi đã có kinh nghiệm, bạn thậm chí có thể yêu cầu AI tích hợp API mô hình bên ngoài hoặc cơ sở dữ liệu), lại một lần nữa: bạn chỉ cần mô tả yêu cầu bằng ngôn ngữ tự nhiên.</p><p>Đây là lợi thế cốt lõi của vibecoding: bạn không cần phải đào sâu vào mã để liên kết sự kiện hoặc logic tọa độ. Bạn trực tiếp nói cho AI biết bạn muốn gì. Ví dụ, trong hộp thoại Trae bạn có thể viết:</p><p>Thay nút bằng điều khiển cần analog. Khi người dùng nhả cần, rắn nên tiếp tục di chuyển theo hướng hiện tại cho đến hành động cần tiếp theo.</p><p>Miễn là yêu cầu rõ ràng, AI sẽ tự động định vị tệp mục tiêu và sửa đổi kiểu điều khiển, liên kết tương tác và logic xử lý hướng.</p><p><img src="'+C+'" alt=""></p><p>Sau khi sửa đổi, quay lại WeChat DevTools để kiểm tra. Nếu thay đổi không hiển thị ngay lập tức, nhấp &quot;Run&quot; trong DevTools hoặc làm mới cửa sổ xem trước để áp dụng bản xây dựng mới nhất. Nếu vẫn chưa cập nhật, dừng chạy trong HBuilderX và chạy lại trên trình mô phỏng, sau đó bạn có thể thấy mini program đã cập nhật:</p><p><img src="'+x+'" alt=""></p><h2 id="_3-5-neu-xuat-hien-van-đe-tiep-tuc-giao-tiep-bang-ngon-ngu-tu-nhien" tabindex="-1">3.5 Nếu Xuất hiện Vấn đề: Tiếp tục Giao tiếp bằng Ngôn ngữ Tự nhiên <a class="header-anchor" href="#_3-5-neu-xuat-hien-van-đe-tiep-tuc-giao-tiep-bang-ngon-ngu-tu-nhien" aria-label="Permalink to “3.5 Nếu Xuất hiện Vấn đề: Tiếp tục Giao tiếp bằng Ngôn ngữ Tự nhiên”">​</a></h2><p>Các phiên bản do AI tạo ra không phải lúc nào cũng hoàn hảo ngay từ đầu. Bạn có thể gặp:</p><ul><li>lỗi thời gian chạy và ứng dụng không mở được;</li><li>tính năng nhìn chung đúng nhưng chi tiết khác với kỳ vọng của bạn;</li><li>UI sử dụng được nhưng vẫn chưa đẹp hoặc tiện dụng đủ.</li></ul><p>Đây những lúc này, không cần tự mù quáng chỉnh sửa mã. Mô tả vấn đề trực tiếp cho trợ lý AI Trae bằng ngôn ngữ tự nhiên, ví dụ:</p><p>&quot;Điều khiển cần analog giờ đã hoạt động, nhưng con rắn đôi khi đột ngột dừng lại. Vui lòng kiểm tra triển khai hiện tại.&quot; Hoặc: &quot;Trò chơi giờ đã chơi được, nhưng giao diện cảm thấy chật chội. Tôi muốn khoảng cách dọc nhiều hơn trên điện thoại. Vui lòng điều chỉnh bố cục.&quot;</p><p>AI sẽ sử dụng ngữ cảnh dự án hiện tại + mô tả của bạn, sau đó cung cấp và áp dụng thay đổi mã trực tiếp. Nếu kết quả trở nên tệ hơn hoặc hướng sai, bạn vẫn có thể rollback về phiên bản ổn định trước đó và thử cách diễn đạt khác.</p><p>Thông qua nhiều vòng như vậy, bạn có thể đánh bóng từ &quot;phiên bản đầu tiên thô&quot; đến một Rắn điều khiển bằng cần analog gần hơn với sở thích của bạn. Ví dụ, tôi cung cấp hình ảnh tham khảo kiểu dáng và yêu cầu AI điều chỉnh kiểu UI tương ứng:</p><p><img src="'+P+'" alt=""></p><h2 id="_3-6-ket-qua-cuoi-cung-va-tom-tat-phan" tabindex="-1">3.6 Kết quả Cuối cùng và Tóm tắt Phần <a class="header-anchor" href="#_3-6-ket-qua-cuoi-cung-va-tom-tat-phan" aria-label="Permalink to “3.6 Kết quả Cuối cùng và Tóm tắt Phần”">​</a></h2><p>Sau nhiều vòng lặp <strong>mô tả ngôn ngữ tự nhiên -&gt; AI sửa đổi -&gt; xem trước trong WeChat DevTools -&gt; tiếp tục tinh chỉnh nhỏ</strong>, tôi cuối cùng có được kết quả này:</p><ul><li>trang trò chơi hoàn chỉnh;</li><li>con rắn di chuyển mượt mà và ăn thức ăn;</li><li>hỗ trợ điều khiển cần analog;</li><li>chạy đúng trong trình mô phỏng mini program.</li></ul><p>Ví dụ sản phẩm cuối cùng:</p><p><img src="'+I+'" alt=""><img src="'+W+'" alt=""><img src="'+D+'" alt=""></p><p>Trong phần này, bạn đã thấy một vòng lặp khép kín hoàn chỉnh:</p><ol><li>Trong Trae, một chỉ dẫn rõ ràng đã để AI xây dựng phiên bản mini program Rắn đầu tiên;</li><li>Với HBuilderX + WeChat DevTools, xác nhận hiệu ứng thực tế từ góc độ người dùng;</li><li>Tiếp tục đề xuất sửa đổi bằng ngôn ngữ tự nhiên, để AI xử lý tối ưu tính năng và UI;</li><li>Khi vấn đề xuất hiện, sử dụng rollback + chạy lại để giữ quy trình an toàn.</li></ol><p>Tiếp theo, bạn có thể sử dụng cùng nhịp độ cho ý tưởng của riêng mình: không giới hạn ở Rắn mà còn mini program tiện ích, trang sự kiện hoặc nguyên mẫu kinh doanh thực tế. Nhiệm vụ chính của bạn là suy nghĩ rõ ràng và mô tả rõ ràng. Để AI và công cụ lo phần còn lại.</p><h1 id="_4-phat-hanh-mini-program" tabindex="-1">4. Phát hành Mini Program <a class="header-anchor" href="#_4-phat-hanh-mini-program" aria-label="Permalink to “4. Phát hành Mini Program”">​</a></h1><p>Trong ba chương trước, chúng ta đã hoàn thành quy trình đầy đủ từ <strong>thiết lập môi trường</strong> -&gt; <strong>phát triển có hỗ trợ AI</strong> -&gt; <strong>chạy Rắn trong trình mô phỏng cục bộ</strong>.</p><p>Từ chương này, câu hỏi then chốt trở thành: <strong>làm thế nào để thực sự xuất bản tác phẩm này lên WeChat, để nó không chỉ là đồ chơi mà là một mini program sử dụng được?</strong></p><p>Để giảm độ khó, trước tiên chúng ta thực hiện <strong>vòng lặp ngắn nhất</strong>: chỉ phát hành dưới dạng <strong>phiên bản thử nghiệm/trải nghiệm</strong> cho chính bạn và một vài đồng đội. Sau khi tính năng và trải nghiệm ổn định, sau đó mới tiến đến phát hành công khai chính thức.</p><p>Chương này trước hết bao gồm 4.1 để hoàn thành đường ngắn nhất cho <strong>phát hành phiên bản trải nghiệm</strong>. Phát hành chính thức cho tất cả người dùng được giải thích trong 4.2.</p><h2 id="_4-1-sop-ngan-nhat-ra-mat-duoi-dang-phien-ban-trai-nghiem" tabindex="-1">4.1 SOP Ngắn nhất - Ra mắt dưới dạng Phiên bản Trải nghiệm <a class="header-anchor" href="#_4-1-sop-ngan-nhat-ra-mat-duoi-dang-phien-ban-trai-nghiem" aria-label="Permalink to “4.1 SOP Ngắn nhất - Ra mắt dưới dạng Phiên bản Trải nghiệm”">​</a></h2><p>Mục tiêu của phần phụ này chỉ có một điều: để bạn mở mini program Rắn của mình trong WeChat dưới dạng một <strong>phiên bản trải nghiệm</strong>.</p><p>Toàn bộ quy trình là bốn nhiệm vụ:</p><ol><li>Tìm và xác nhận AppID của bạn trong Nền tảng Chính thức WeChat.</li><li>Cấu hình AppID này trong dự án của bạn.</li><li>Tải lên phiên bản hiện tại trong WeChat DevTools.</li><li>Quay lại Nền tảng Chính thức và đặt phiên bản đã tải lên này là &quot;Phiên bản Trải nghiệm.&quot;</li></ol><p>Hãy đi theo thứ tự này.</p><h3 id="_4-1-1-xac-nhan-appid-trong-nen-tang-chinh-thuc-wechat" tabindex="-1">4.1.1 Xác nhận AppID trong Nền tảng Chính thức WeChat <a class="header-anchor" href="#_4-1-1-xac-nhan-appid-trong-nen-tang-chinh-thuc-wechat" aria-label="Permalink to “4.1.1 Xác nhận AppID trong Nền tảng Chính thức WeChat”">​</a></h3><p>Bước đầu tiên: xác nhận AppID mini program của bạn trong Nền tảng Chính thức WeChat.</p><p>Bạn đã làm việc này một lần trong <strong>Phần 2 Thiết lập Môi trường</strong>. Ở đây chúng ta sử dụng nó thực sự.</p><ol><li>Truy cập <code>https://mp.weixin.qq.com</code> và đăng nhập vào backend mini program của bạn.</li><li>Tìm &quot;Development Management&quot; trong menu bên trái, sau đó vào &quot;Development Settings.&quot;</li><li>Ở phía trên, tìm khu vực &quot;Developer ID.&quot; Có một dòng &quot;AppID (Mini Program ID)&quot; - đây là ID duy nhất của bạn.</li></ol><p>ID này phải khớp chính xác với cấu hình dự án. Nếu không WeChat sẽ xem nó là một định danh ứng dụng khác và xem trước/phát hành sẽ thất bại.</p><p><img src="'+f+'" alt=""></p><h3 id="_4-1-2-đien-appid-vao-du-an" tabindex="-1">4.1.2 Điền AppID vào Dự án <a class="header-anchor" href="#_4-1-2-đien-appid-vao-du-an" aria-label="Permalink to “4.1.2 Điền AppID vào Dự án”">​</a></h3><p>Bước thứ hai: viết AppID này vào cấu hình dự án để ánh xạ bản xây dựng cục bộ đến tài khoản mini program chính thức của bạn.</p><p>Nếu dự án của bạn sử dụng mẫu uni-app, làm như sau:</p><ol><li>Mở HBuilderX và tải dự án Rắn.</li><li>Tìm <code>manifest.json</code> trong cây tệp và mở nó.</li><li>Cuộn đến &quot;WeChat Mini Program Configuration&quot; và bạn sẽ thấy ô nhập liệu như &quot;WeChat Mini Program AppID.&quot;</li><li>Dán AppID đã sao chép từ Nền tảng Chính thức chính xác và lưu tệp. <img src="'+A+'" alt=""></li></ol><p>Giờ dự án cục bộ của bạn đã xác nhận định danh mini program này. Tiếp theo, khi bạn tải lên từ WeChat DevTools, nó sẽ được ghi dưới AppID này.</p><h3 id="_4-1-3-tai-len-phien-ban-trong-wechat-devtools" tabindex="-1">4.1.3 Tải lên Phiên bản trong WeChat DevTools <a class="header-anchor" href="#_4-1-3-tai-len-phien-ban-trong-wechat-devtools" aria-label="Permalink to “4.1.3 Tải lên Phiên bản trong WeChat DevTools”">​</a></h3><p>Chúng ta đã chạy dự án vào WeChat DevTools để xem trước trên trình mô phỏng.</p><p>Bây giờ chúng ta làm: &quot;đóng gói mã hiện tại thành một phiên bản và tải lên máy chủ.&quot;</p><p>Các bước:</p><ol><li>Trong thanh công cụ phía trên bên phải của WeChat DevTools, nhấp &quot;Upload.&quot;</li><li>Trong cửa sổ popup, điền hai trường chính: <ol><li>Số phiên bản: ví dụ <code>1.0.0</code> (chỉ số và dấu chấm).</li><li>Ghi chú dự án: mô tả ngắn, như &quot;Hoàn thành lối chơi cốt lõi.&quot;</li></ol></li><li>Xác nhận và nhấp &quot;Upload.&quot; Bảng đầu ra hiển thị quá trình xây dựng. Nếu tất cả các bước chuyển sang màu xanh và tải lên hoàn tất, phiên bản này đã được gửi thành công đến máy chủ WeChat.</li></ol><p><img src="'+w+'" alt=""></p><p><img src="'+B+'" alt=""></p><p><img src="'+N+'" alt=""><img src="'+M+'" alt=""></p><h3 id="_4-1-4-đat-phien-ban-đa-tai-len-lam-phien-ban-trai-nghiem-trong-backend" tabindex="-1">4.1.4 Đặt Phiên bản đã Tải lên làm Phiên bản Trải nghiệm trong Backend <a class="header-anchor" href="#_4-1-4-đat-phien-ban-đa-tai-len-lam-phien-ban-trai-nghiem-trong-backend" aria-label="Permalink to “4.1.4 Đặt Phiên bản đã Tải lên làm Phiên bản Trải nghiệm trong Backend”">​</a></h3><p>Tải lên chỉ gửi mã đến phía WeChat. Bạn vẫn cần nói cho hệ thống &quot;đây là một phiên bản trải nghiệm.&quot;</p><p>Bước cuối cùng: quay lại backend Nền tảng Chính thức và hoàn tất vòng lặp.</p><ol><li><p>Mở <code>https://mp.weixin.qq.com</code> và vào backend mini program.</p></li><li><p>Trong menu bên trái, tìm &quot;Management&quot; -&gt; &quot;Version Management.&quot;</p></li><li><p>Trong phần &quot;Development Version,&quot; bạn sẽ thấy phiên bản đã tải lên: phiên bản <code>1.0.0</code>, ghi chú của bạn và dấu thời gian vừa tải lên.</p></li><li><p>Ở bên phải hàng này, sử dụng menu thả xuống/nút hành động để chọn &quot;Set as Experience Version,&quot; xác nhận hành động. Trước bước này, đảm bảo danh mục chính đã được cấu hình trên trang chủ/cài đặt danh mục.</p><p><img src="'+S+'" alt=""></p><p><img src="'+R+'" alt=""></p></li></ol><p>Sau khi hoàn tất, phiên bản này trở thành &quot;Phiên bản Trải nghiệm&quot; mini program của bạn. Bạn có thể tạo mã QR trải nghiệm trong backend, hoặc thêm chính mình/đội ngũ làm thành viên trải nghiệm, sau đó quét trong WeChat để thử nghiệm trên thiết bị thật.</p><p>Đến đây, chúng ta đã hoàn thành vòng lặp ngắn nhất từ dự án cục bộ đến phát hành thử nghiệm:</p><p>Bạn không cần mở cho tất cả người dùng WeChat ngay lập tức. Trong phạm vi an toàn, chạy mini program thực trong môi trường WeChat thực. Đủ cho thử nghiệm tính năng, thu thập phản hồi và lặp lại.</p><h2 id="_4-2-ra-mat-chinh-thuc-mini-program" tabindex="-1">4.2 Ra mắt Chính thức Mini Program <a class="header-anchor" href="#_4-2-ra-mat-chinh-thuc-mini-program" aria-label="Permalink to “4.2 Ra mắt Chính thức Mini Program”">​</a></h2><p>Sau khi phiên bản trải nghiệm chạy tốt, bạn đã có thể chơi mini program Rắn này trong WeChat của riêng mình. Bước tiếp theo là chuyển từ người dùng trải nghiệm hạn chế sang một mini program WeChat hoàn toàn công khai.</p><p>Chia thành các bước: hoàn thành thông tin cơ bản, chọn danh mục, hoàn tất nộp hồ sơ, sau đó gửi kiểm duyệt. Làm theo thứ tự này:</p><h3 id="_4-2-1-vao-quy-trinh-phat-hanh-mini-program" tabindex="-1">4.2.1 Vào Quy trình Phát hành Mini Program <a class="header-anchor" href="#_4-2-1-vao-quy-trinh-phat-hanh-mini-program" aria-label="Permalink to “4.2.1 Vào Quy trình Phát hành Mini Program”">​</a></h3><p>Trước tiên quay lại backend Nền tảng Chính thức WeChat và đăng nhập. Trong điều hướng bên trái tìm các mục liên quan đến &quot;Version Management / Release&quot; (UI có thể thay đổi nhẹ theo thời gian). Bạn sẽ tìm thấy &quot;Mini Program Release Flow.&quot;</p><p>Sau khi vào, khu vực phía trên hiển thị thanh tiến trình. Bên dưới liệt kê các bước như:</p><ol><li>Mini Program Information</li><li>Mini Program Category</li><li>Operation Information / Filing</li><li>WeChat Verification (tùy thuộc vào loại thực thể)</li></ol><p>Ban đầu tiến trình là 0%. Khi mỗi bước hoàn thành, hệ thống tự động cập nhật.</p><p><img src="'+H+'" alt=""></p><h3 id="_4-2-2-đien-thong-tin-co-ban-mini-program" tabindex="-1">4.2.2 Điền Thông tin Cơ bản Mini Program <a class="header-anchor" href="#_4-2-2-đien-thong-tin-co-ban-mini-program" aria-label="Permalink to “4.2.2 Điền Thông tin Cơ bản Mini Program”">​</a></h3><p>Bước đầu tiên là hoàn thành &quot;danh thiếp&quot; mini program của bạn, là những gì người dùng thấy đầu tiên trong WeChat.</p><p>Trên trang &quot;Mini Program Information,&quot; bạn thường cần điền/xác nhận:</p><ol><li>Tên mini program Nó xuất hiện trong kết quả tìm kiếm và tiêu đề ứng dụng. Có giới hạn độ dài và quy tắc đặt tên. Chọn tên mô tả chức năng và dễ nhớ.</li><li>Mô tả / giới thiệu Sử dụng một hoặc hai câu để giải thích mini program này làm gì, ví dụ: &quot;Trò chơi Rắn được phát triển bằng lập trình có hỗ trợ AI, phù hợp chơi giải trí nhanh.&quot; Giữ mô tả nhất quán với chức năng thực tế và tránh văn bản tiếp thị phóng đại.</li><li>Biểu tượng và ảnh chụp màn hình <ol><li>Biểu tượng thường yêu cầu hình vuông với hỗ trợ PNG/JPG và giới hạn kích thước/pixel (kiểm tra quy tắc trang). Sử dụng biểu tượng đơn giản, độ tương phản cao.</li><li>Tải lên một số ảnh chụp màn hình như trang chủ, trang trò chơi, trang cài đặt. Chúng giúp người dùng hiểu nội dung.</li></ol></li><li>Các trường bắt buộc khác Như thẻ và khu vực dịch vụ, điền theo hướng dẫn. Chỉ một nguyên tắc: tất cả thông tin phải khớp với chức năng thực tế của mini program Rắn của bạn.</li></ol><p><img src="'+X+'" alt=""></p><p>Sau khi tất cả các trường hoàn tất, nhấp Save hoặc Next. Bước đầu tiên trong quy trình phát hành hoàn tất.</p><h3 id="_4-2-3-chon-danh-muc-dich-vu-mini-program" tabindex="-1">4.2.3 Chọn Danh mục Dịch vụ Mini Program <a class="header-anchor" href="#_4-2-3-chon-danh-muc-dich-vu-mini-program" aria-label="Permalink to “4.2.3 Chọn Danh mục Dịch vụ Mini Program”">​</a></h3><p>Sau khi thông tin cơ bản xong, hướng dẫn đưa bạn đến &quot;Mini Program Category.&quot; Danh mục là phân loại ứng dụng của bạn trong WeChat, ảnh hưởng đến lộ trình kiểm duyệt và hiển thị/vận hành sau này.</p><p><img src="'+V+'" alt=""></p><p>Trên trang này bạn sẽ thấy &quot;Add Category.&quot; Nhấp vào đó và chọn danh mục phù hợp trong cây danh mục hệ thống, ví dụ:</p><p><img src="'+K+'" alt=""></p><ol><li>Chọn &quot;Education&quot; làm danh mục cấp cao nhất;</li><li>Sau đó chọn danh mục phụ cụ thể hơn như &quot;Education Tools / Teaching Assistant.&quot; Trong ví dụ này, công cụ giáo dục được chọn làm trợ trợ học tập cho vibecoding.</li></ol><p>Trong dự án của riêng bạn, chỉ cần chọn danh mục phù hợp nhất theo trường hợp sử dụng thực tế.</p><p><img src="'+G+'" alt=""></p><p><img src="'+Q+'" alt=""></p><p>Sau khi xác nhận danh mục, nhấp Save. Nếu trang hiển thị &quot;category created successfully&quot; và hiển thị mục mới của bạn, bước này hoàn tất.</p><h3 id="_4-2-4-hoan-tat-thong-tin-nop-ho-so" tabindex="-1">4.2.4 Hoàn tất Thông tin Nộp hồ sơ <a class="header-anchor" href="#_4-2-4-hoan-tat-thong-tin-nop-ho-so" aria-label="Permalink to “4.2.4 Hoàn tất Thông tin Nộp hồ sơ”">​</a></h3><p>Tiếp theo, quy trình phát hành yêu cầu &quot;Operation Information / Filing.&quot; Điều này xác minh thực thể chịu trách nhiệm đằng sau mini program.</p><p><img src="'+L+'" alt=""></p><p>Trong ví dụ thực thể cá nhân, quy trình thường bao gồm:</p><ol><li>Chọn loại nộp hồ sơ Chọn giữa các loại như &quot;Individual&quot; hoặc &quot;Enterprise,&quot; phù hợp với thực thể đăng ký của bạn.</li><li>Điền thông tin thực thể Bao gồm tên, loại giấy tờ, số giấy tờ, v.v. Phải khớp với thông tin đăng ký, nếu không kiểm duyệt có thể từ chối.</li><li>Tải lên tài liệu hỗ trợ Thường yêu cầu ảnh giấy tờ tùy thân hoặc tệp chứng minh khác, với yêu cầu định dạng/kích thước/độ nét cụ thể hiển thị trên trang. Chuẩn bị và tải lên tệp rõ ràng. <img src="'+O+'" alt=""></li></ol><p>Sau khi gửi, hệ thống chuyển sang &quot;đang được kiểm duyệt&quot; và hiển thị thông báo như &quot;Information submitted, please wait.&quot; Việc này có thể mất một thời gian. Bạn có thể kiểm tra tiến độ bất kỳ lúc nào trong backend.</p><p><img src="'+U+'" alt=""></p><h3 id="_4-2-5-gui-kiem-duyet-va-đoi-phat-hanh-chinh-thuc" tabindex="-1">4.2.5 Gửi Kiểm duyệt và Đợi Phát hành Chính thức <a class="header-anchor" href="#_4-2-5-gui-kiem-duyet-va-đoi-phat-hanh-chinh-thuc" aria-label="Permalink to “4.2.5 Gửi Kiểm duyệt và Đợi Phát hành Chính thức”">​</a></h3><p>Khi &quot;Mini Program Information,&quot; &quot;Category&quot; và &quot;Operation Information/Filing&quot; đều hoàn tất, thực hiện hành động cuối cùng: gửi kiểm duyệt.</p><ol><li>Quay lại trang tổng quan quy trình phát hành và xác nhận tất cả mục hiển thị hoàn tất, với tiến trình gần 100%.</li><li>Nhấp &quot;Submit for Review&quot; (hoặc nút tương tự) để gửi phiên bản phát triển hiện tại đến đội kiểm duyệt WeChat.</li><li>Trong &quot;Version Management,&quot; trạng thái phiên bản này trở thành &quot;Under Review.&quot; Sau khi được phê duyệt nó trở thành &quot;Published&quot; hoặc sẵn sàng để &quot;Go Live.&quot;</li></ol><p>Nếu kiểm duyệt hồ sơ thất bại, nhà phát triển có thể nhận được cuộc gọi chỉ định các phần thất bại.</p><p>Đối với hồ sơ, bạn có thể nhận mã xác nhận và liên kết xác nhận từ Bộ Công nghiệp và Công nghệ Thông tin. Mở liên kết và điền mã + thông tin cá nhân (xác nhận có hiệu lực 1 ngày). Nếu hồ sơ vượt qua, bạn nhận email và SMS thông báo với số hồ sơ. Xác minh WeChat: cá nhân thường trả 30 CNY, doanh nghiệp khoảng 300 CNY. Phí không hoàn lại bất kể kết quả phê duyệt. Bạn có thể nhận thông báo xác minh và cuộc gọi xác nhận.</p><p>Khi gửi kiểm duyệt, tải lên video hoạt ảnh/ảnh chụp màn hình và điền thông tin yêu cầu. Sau đó nhấp &quot;Submit Release&quot; để phát hành chính thức.</p><p><img src="'+E+'" alt=""></p><h1 id="_5-tom-tat" tabindex="-1">5. Tóm tắt <a class="header-anchor" href="#_5-tom-tat" aria-label="Permalink to “5. Tóm tắt”">​</a></h1><p>Đến đây, bạn đã hoàn thành một vòng lặp phát triển mini program đầy đủ <strong>từ 0 đến 1</strong>: từ việc hiểu mini program, đến cài đặt Trae, HBuilderX và WeChat DevTools; từ việc đưa ý tưởng cho AI và để nó &quot;xây gạch&quot; trong mã, đến chơi phiên bản Rắn đầu tiên trong trình mô phỏng; sau đó đóng gói thành phiên bản trải nghiệm, hoàn tất hồ sơ/kiểm duyệt và làm cho nó thực sự sử dụng được trong WeChat - bạn đã tự mình chạy qua toàn bộ chuỗi một lần.</p><p>Quan trọng hơn, bạn đạt được điều này không phải bằng cách ghi nhớ cú pháp. Bạn đạt được bằng cách thể hiện yêu cầu rõ ràng + giao tiếp hiệu quả với AI. Bạn đã trải nghiệm điều này: <strong>một chỉ dẫn bằng ngôn ngữ tự nhiên có thể để AI đáp ứng nhu cầu phát triển của bạn rất hiệu quả</strong>. Khả năng này không giới hạn ở Rắn. Nó có thể chuyển sang bất kỳ mini program nào bạn muốn xây dựng sau này - công cụ, trang sự kiện, ứng dụng giáo dục hoặc dự án công việc thực tế.</p><p>Nếu chúng ta tóm tắt thành một <strong>SOP tổng quát</strong>, chỉ có năm bước: <strong>Làm rõ một yêu cầu nhỏ -&gt; xây dựng khung dự án trong Trae -&gt; sử dụng vibecoding + AI để tạo phiên bản đầu tiên -&gt; liên tục thử nghiệm và cải thiện trong WeChat DevTools -&gt; tải lên, nộp hồ sơ, kiểm duyệt và ra mắt.</strong> Mỗi lần bạn lặp lại năm bước này, bạn có thêm một mini program thực có thể mở và chia sẻ, và thêm một tầng tự tin rằng &quot;tôi có thể sử dụng AI để biến ý tưởng thành sản phẩm.&quot;</p><p>Tiếp theo, bạn có thể tiếp tục đánh bóng ứng dụng Rắn này hoặc đóng nó lại và bắt đầu một dự án trắng từ ý tưởng riêng. Bất kể bạn xây dựng gì, hãy nhớ một điều: bạn không còn chỉ là người &quot;muốn xây dựng gì đó.&quot; Bạn đã là một nhà phát triển vibecoding đã chạy qua toàn bộ quy trình làm việc. Phần còn lại là lặp lại cho đến khi khả năng này trở thành thói quen.</p><h1 id="tai-lieu-tham-khao" tabindex="-1">Tài liệu Tham khảo: <a class="header-anchor" href="#tai-lieu-tham-khao" aria-label="Permalink to “Tài liệu Tham khảo:”">​</a></h1><ul><li><a href="https://zhuanlan.zhihu.com/p/1889401120939567074" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/1889401120939567074</a></li><li><a href="https://blog.csdn.net/2401_87407347/article/details/155193007" target="_blank" rel="noreferrer">https://blog.csdn.net/2401_87407347/article/details/155193007</a></li></ul>',195)])])}const hn=t(z,[["render",F]]);export{tn as __pageData,hn as default};
